package com.hau.ai.application.service;import com.hau.ai.application.port.out.*;import com.hau.ai.domain.exception.*;import com.hau.ai.domain.model.*;import java.time.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class AiJobService{private final AiJobRepository jobs;private final DocumentRepository docs;private final AiEventPublisher events;private final Clock clock;public AiJobService(AiJobRepository j,DocumentRepository d,AiEventPublisher e,Clock c){jobs=j;docs=d;events=e;clock=c;}@Transactional public AiJob create(UUID user,UUID document,JobType type,String request,UUID correlation){if(document!=null){var d=docs.findById(document).orElseThrow(()->new NotFoundException("Document not found"));if(!d.ownerId().equals(user))throw new NotFoundException("Document not found");}var job=jobs.save(AiJob.pending(UUID.randomUUID(),user,document,type,request,Instant.now(clock)));events.requested(job,correlation);return job;}@Transactional(readOnly=true)public AiJob get(UUID id,UUID user){var j=jobs.findById(id).orElseThrow(()->new NotFoundException("AI job not found"));if(!j.requestedBy().equals(user))throw new NotFoundException("AI job not found");return j;}}
